def plan(no,title,scope):
 if no in CRIM:
  steps=['Утврдете го точното процесно својство, фазата на постапката и дали постои итен рок или мерка.','Обезбедете ги актите и доказите: покана/наредба/решение, записници, списи, материјални и дигитални докази.','Проверете ја законитоста на прибирањето и употребата на доказите и почитувањето на правото на адвокат и правично судење.','Одделно анализирајте ги фактите од правната квалификација; проверете вина, причинска врска, штета/корист и алтернативни објаснувања.','Подгответе конкретно дејствие: приговор, доказен предлог, жалба, барање или друга заштита, со контролирани рокови.','Пред поднесување, адвокатот го проверува важечкиот КЗ/ЗКП, посебниот закон и релевантната судска пракса.']
  sources=['Закон за кривичната постапка — тековен официјален текст/измена','Кривичен законик — тековен официјален текст/измена','Релевантна пракса на Врховниот суд, Уставниот суд и ЕСЧП според конкретното прашање']
 elif no in ADMIN:
  steps=['Идентификувајте го органот, управниот акт/барање и точната фаза на постапката.','Прочитајте ја правната поука и евидентирајте датум на доставување/поднесување; не претпоставувајте рок.','Соберете го целосното управно досие, докази за доставување и претходна комуникација.','Определете го точниот правен лек според ЗОУП, ЗУС и посебниот закон.','Формулирајте барање со факти, правен основ, докази и јасен предлог; зачувајте доказ за прием.','Пред поднесување, повторно проверете важечки официјален текст и евентуални одлуки на Уставниот суд.']
  sources=['Закон за општата управна постапка — официјален извор','Закон за управните спорови — официјален извор','Посебен материјален закон и правната поука во конкретниот акт']
 elif no in NOTARY:
  steps=['Утврдете ја точната правна работа и дали е доволна заверка или е потребна посебна нотарска форма.','Проверете идентитет, деловна способност, полномошно и оригиналност на документите.','Проверете дали закон бара солемнизација, нотарски акт, сведоци, превод или дополнителна согласност.','Подгответе чист текст без празнини/двосмислености и усогласете ги податоците со јавните регистри.','Пред потпис проверете трошоци, даноци/такси и важечката нотарска тарифа.','Земете заверен примерок и проверете дали се потребни апостил, превод или дополнителна регистрација.']
  sources=['Закон за нотаријатот — важечки официјален текст','Нотарска тарифа и релевантни подзаконски акти','Посебниот закон што ја уредува конкретната правна работа']
 else:
  steps=['Утврдете го надлежниот орган/субјект и правната цел.','Соберете ги документите и доказите што ја потврдуваат фактичката состојба.','Проверете го важечкиот материјален и процесен пропис и конкретната правна поука.','Поднесете јасно образложено барање/приговор со прилози и доказ за прием.','Следете го предметот и роковите без да се потпирате на општа претпоставка.','Пред следен правен чекор направете професионална проверка на официјалните извори.']
  sources=['Официјален текст на релевантниот закон и измени','Надлежен орган/фонд/регистар — тековна постапка и обрасци','Релевантна судска или управна пракса кога е применлива']
 checklist=['Точно е утврдена надлежноста и процесното својство','Постојат копии од клучните акти и докази','Датумите на доставување/поднесување се документирани','Рокот е проверен во официјален извор и конкретна правна поука','Фактите се одвоени од правната оценка','Пред конечна одлука е направен Human Gate од адвокат']
 warnings=['Не користете општ рок ако посебен закон или правната поука предвидуваат друго.','Водичот не е доказ за важечко право; официјалниот текст и конкретниот акт имаат предност.']
 if no in {'40','59'}: warnings.append('ЗПП 151/2026 има временски режим; за постапки околу 18.01.2027 проверете која верзија се применува.')
